function Score({ score }) {
	return (
		<tr className="result-score-tr" key={score.id}>
			<td className="result-score-td">{score.homeTeam}</td>
			<td className="result-score-td">{score.result}</td>
			<td className="result-score-td">{score.awayTeam}</td>
		</tr>
	);
}
export default Score;
